import * as MP4 from '../vendor/mp4-muxer.js';import * as WEBM from '../vendor/webm-muxer.js';
export const yieldUI=()=>new Promise(ok=>setTimeout(ok,0));
export async function capabilities(width,height,fps,audio){const bitrate=Math.max(1500000,width*height*fps*.14);if(globalThis.VideoEncoder&&globalThis.VideoFrame&&(!audio||(globalThis.AudioEncoder&&globalThis.AudioData))){for(const candidate of [{format:'mp4',video:'avc1.420033',audio:'mp4a.40.2',videoMux:'avc',audioMux:'aac',lib:MP4},{format:'webm',video:'vp09.00.10.08',audio:'opus',videoMux:'V_VP9',audioMux:'A_OPUS',lib:WEBM},{format:'webm',video:'vp8',audio:'opus',videoMux:'V_VP8',audioMux:'A_OPUS',lib:WEBM}]){try{const videoConfig={codec:candidate.video,width,height,bitrate,framerate:fps,latencyMode:'quality',...(candidate.format==='mp4'?{avc:{format:'avc'}}:{})};const audioConfig={codec:candidate.audio,sampleRate:48000,numberOfChannels:2,bitrate:128000};if((await VideoEncoder.isConfigSupported(videoConfig)).supported&&(!audio||(await AudioEncoder.isConfigSupported(audioConfig)).supported))return {...candidate,videoConfig,audioConfig,kind:'frames'};}catch{}}}if(globalThis.MediaRecorder&&HTMLCanvasElement.prototype.captureStream){const mime=['video/mp4;codecs=avc1.42E01E,mp4a.40.2','video/mp4','video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm'].find(x=>MediaRecorder.isTypeSupported(x));if(mime)return {kind:'realtime',mime,format:mime.includes('mp4')?'mp4':'webm'};}return null;}
export async function encodeFrames(renderer,p,cap,audio,signal,progress){const target=new cap.lib.ArrayBufferTarget(),muxer=new cap.lib.Muxer({target,video:{codec:cap.videoMux,width:renderer.canvas.width,height:renderer.canvas.height,frameRate:p.fps},...(audio?{audio:{codec:cap.audioMux,sampleRate:48000,numberOfChannels:2}}:{}),...(cap.format==='mp4'?{fastStart:'in-memory',firstTimestampBehavior:'offset'}:{firstTimestampBehavior:'offset'})});let error;const video=new VideoEncoder({output:(chunk,meta)=>muxer.addVideoChunk(chunk,meta),error:e=>error=e});let encoder,firstAudioTimestamp;const total=Math.ceil(p.duration*p.fps);const check=()=>{if(signal.aborted)throw new DOMException('Render cancelled','AbortError');if(error)throw error;};try{video.configure(cap.videoConfig);if(audio){encoder=new AudioEncoder({output:(chunk,meta)=>{firstAudioTimestamp??=chunk.timestamp;const timestamp=chunk.timestamp-firstAudioTimestamp,remaining=Math.round(p.duration*1e6)-timestamp;if(remaining<=0)return;const bytes=new Uint8Array(chunk.byteLength);chunk.copyTo(bytes);muxer.addAudioChunkRaw(bytes,chunk.type,timestamp,Math.min(chunk.duration||21333,remaining),meta);},error:e=>error=e});encoder.configure(cap.audioConfig);const step=1024;for(let i=0;i<audio.length;i+=step){check();const size=Math.min(step,audio.length-i),data=new Float32Array(size*2);for(let c=0;c<2;c++)data.set(audio.getChannelData(c).subarray(i,i+size),c*size);const frame=new AudioData({format:'f32-planar',sampleRate:48000,numberOfFrames:size,numberOfChannels:2,timestamp:Math.round(i/48000*1e6),data});try{encoder.encode(frame);}finally{frame.close();}if(encoder.encodeQueueSize>30){await encoder.flush();await yieldUI();}}await encoder.flush();}for(let i=0;i<total;i++){check();await renderer.frame(i/p.fps);const duration=Math.round(Math.min(1/p.fps,p.duration-i/p.fps)*1e6),frame=new VideoFrame(renderer.canvas,{timestamp:Math.round(i/p.fps*1e6),duration});try{video.encode(frame,{keyFrame:i%Math.max(1,p.fps*2)===0});}finally{frame.close();}progress(i+1,total);if(video.encodeQueueSize>6)await video.flush();await yieldUI();}await video.flush();check();muxer.finalize();if(cap.format==='webm')fixWebMDuration(target.buffer,p.duration);return new Blob([target.buffer],{type:`video/${cap.format}`});}finally{video.close();if(encoder?.state!=='closed')encoder?.close();}}
export async function encodeRealtime(renderer,p,cap,audio,signal,progress){await renderer.frame(0);const stream=renderer.canvas.captureStream(p.fps),videoTrack=stream.getVideoTracks()[0];let ctx,source,destination;const chunks=[],total=Math.ceil(p.duration*p.fps);let recorder;try{if(audio){ctx=new AudioContext({sampleRate:48000});await ctx.resume();source=ctx.createBufferSource();source.buffer=audio;destination=ctx.createMediaStreamDestination();source.connect(destination);destination.stream.getAudioTracks().forEach(t=>stream.addTrack(t));}recorder=new MediaRecorder(stream,{mimeType:cap.mime,videoBitsPerSecond:Math.max(2000000,renderer.canvas.width*renderer.canvas.height*p.fps*.14)});const done=new Promise((ok,no)=>{recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=ok;recorder.onerror=e=>no(e.error||Error('Recorder failed'));});recorder.start(200);source?.start();const start=performance.now();for(let i=0;i<total;i++){if(signal.aborted)throw new DOMException('Render cancelled','AbortError');if(document.hidden)throw Error('Keep this tab visible during compatibility export.');await renderer.frame(i/p.fps);videoTrack.requestFrame?.();progress(i+1,total);const deadline=start+Math.min(p.duration,(i+1)/p.fps)*1000;await new Promise(ok=>setTimeout(ok,Math.max(0,deadline-performance.now())));}if(signal.aborted)throw new DOMException('Render cancelled','AbortError');source?.stop();recorder.stop();await done;if(signal.aborted)throw new DOMException('Render cancelled','AbortError');return new Blob(chunks,{type:recorder.mimeType});}finally{if(recorder?.state==='recording')recorder.stop();try{source?.stop();}catch{}stream.getTracks().forEach(t=>t.stop());if(ctx)await ctx.close();}}

// webm-muxer stores the final frame timestamp as Duration; the timeline ends one frame later.
export function fixWebMDuration(buffer,seconds){const bytes=new Uint8Array(buffer),view=new DataView(buffer);for(let i=0;i<Math.min(bytes.length-11,4096);i++){if(bytes[i]===0x44&&bytes[i+1]===0x89&&bytes[i+2]===0x88){view.setFloat64(i+3,seconds*1000,false);return;}}throw Error('Could not set WebM duration metadata.');}
